\section{Ruling Out $o(\log \secp)$-Depth Strategies}\label{sec:main}
Our main result (\cref{thm:CR-for-depth-bounded-adversaries}) says that the construction in \cref{sec:prelim-YZ-protocol} provides $o(\secp^{c/2})$ bits of min-entropy (for some constant $c$) as long as the adversary is limited to query depth $o(\log \secp)$.

\begin{theorem}[Certifiable Min-Entropy]\label{thm:CR-for-depth-bounded-adversaries}
    The candidate construction of a certifiable min-entropy protocol given in \cref{sec:prelim-YZ-protocol} satisfies $(D, \minent)$-certifiable min-entropy (\cref{def:certifiable-min-entropy}) for any $D(\secp) = o(\log \secp)$ and any $\minent(\secp) = o(\secp^{c/2})$, where $c$ is a constant parameter of the list-recoverable code.
\end{theorem}

The rest of \cref{sec:main} is devoted to proving \cref{thm:CR-for-depth-bounded-adversaries}.\\

Let $(\RO, \bfX)$ be the random variables referring to the random oracle and $\cA$'s output respectively, and let $(\ro, \bfx)$ be generic values that they take. $(\RO, \bfX)$ are jointly sampled from the following distribution. First $\RO \getsr \cH$, and then $\bfX \gets \cA^\RO(1^\secp)$.

\subsection*{The adversary heavily queries their answer.}
First, we prove roughly that if the adversary is able to output a correct answer $\bfx$ with high probability, then they must have given non-negligible query weight to most symbols of $\bfx$. Intuitively, this is because the adversary must check that most symbols of $\bfx$ actually hash to $\mathbf{0}$; otherwise, they would output $\bfx$ even when those symbols hash to $1$.

\begin{lemma}\label{thm:must-heavy-query}
    Let $p$ be any probability $\in (0,1]$, and let $s$ be any value $\in [1,n]$. Let $D, W \geq 1$ be the query depth and width, respectively, of $\cA$, and let $Q = D \cdot W$.

    Over the randomness of $(\RO, \bfX)$, the probability is $\leq 2^{-(s-1)}$ that we sample an $(\ro, \bfx)$ that satisfy all of the following conditions:
    \begin{enumerate}
        \item $\cA^\ro$ gives small query weight to many positions of $\bfx$: There exists \emph{no} set $I \subseteq [n]$ of size $\geq n - s$ such that for all $i \in I$,
        \[w_{i, x_i}^{\leq D}(\ro) \geq \frac{p^2}{16 Q n}\]
        \item $\bfx$ has high probability given $\ro$: $\Pr[\bfX = \bfx |\RO = \ro] \geq p$.
        \item $\bfx$ is correct: $\bfx \in C$ and $\ro(\bfx) = \mathbf{0}$.
    \end{enumerate}
\end{lemma}
\begin{proof}
$ $
    \paragraph{Constructing Good and Bad Sets:} Let $S$ be the set of all pairs $(\ro, \bfx)$ that satisfy the conditions of \cref{thm:must-heavy-query} ($S$ is the ``good'' set). $\Pr[S]$ is the probability that all the conditions of \cref{thm:must-heavy-query} are satisfied, over the randomness of sampling $\ro \gets \cH$ and $\bfx \gets \cA^\ro$. We will show that $\Pr[S] \leq 2^{-(s-1)}$. 

    Next, for each $(\ro,\bfx) \in S$, let us construct a set $T_{\ro, \bfx}$ of ``bad'' pairs $(\ro', \bfx)$ on which $\bfx$ is not correct. 

    Condition 1 implies that for any set $I \subseteq [n]$ of size $\geq n - s$, there exists an $i \in I$ such that \[w_{i, x_i}^{\leq D}(\ro) < \frac{p^2}{16 Q n}\]

    That means there exists another set $I_2 \subseteq [n]$ of size $|I_2| \geq s + 1$ such that for all $i \in I_2$, 
    \[w_{i, x_i}^{\leq D}(\ro) < \frac{p^2}{16 Q n}\]

    To construct $T_{\ro, \bfx}$, choose any non-empty subset of $\{(i, x_i)\}_{i \in I_2}$ and reprogram $\ro$ on these inputs, flipping the output from $0$ to $1$. Let us call the new oracle $\ro'$. Let $T_{\ro, \bfx}$ be the set of all pairs $(\ro', \bfx)$ that can be constructed in this way. 

    \paragraph{Properties:} First
    \[|T_{\ro, \bfx}| = 2^{|I_2|} - 1 \geq 2^{s + 1} - 1 \geq 2^{s}\]

    Second, for any $(\ro', \bfx) \in T_{\ro, \bfx}$, $\bfx$ is not a correct answer for oracle $\ro'$ because $\ro'(\bfx) \neq \mathbf{0}$.

    Third, the sets $T_{\ro, \bfx}$ are disjoint. That is to say, for any two distinct pairs $(h_1, \bfx_1)$ and $(h_2, \bfx_2)$ in $S$, 
    \[T_{h_1, \bfx_1} \cap T_{h_2, \bfx_2} = \emptyset\]
    For any $(\ro', \bfx') \in T_{\ro, \bfx}$, $\bfx = \bfx'$, and $\ro$ can be computed from $(\ro', \bfx')$ by reprogramming $\ro'$ to map $\bfx'$ to $\mathbf{0}$. This procedure computes $(\ro, \bfx)$ from any $(\ro', \bfx') \in T_{\ro, \bfx}$, so the sets $T_{\ro, \bfx}$ must be disjoint.

    Fourth, 
    \begin{claim}
        For any $(\ro', \bfx) \in T_{\ro, \bfx}$,
        \[\frac{1}{2} \cdot \Pr[\bfX = \bfx|\RO = \ro] \leq \Pr[\bfX = \bfx|\RO = \ro']\]
    \end{claim}
    \begin{proof}
    This follows from the swapping lemma (\cref{thm:swapping-lemma}) and \cref{thm:trace-dist-euclidian-dist}. The adversary samples their output $\bfx$ by applying a measurement $M$ to their final state (either $\ket{\psi_D^\ro}$ or $\ket{\psi_D^{\ro'}}$).
    \begin{align*}
        \Pr[\bfX = \bfx|\RO = \ro] - \Pr[\bfX = \bfx|\RO = \ro'] &\leq \mathsf{TraceDist}\left[\ket{\psi_D^{\ro'}}, \ket{\psi_D^{\ro}}\right]\\
        &\leq \left\|\ket{\psi_D^{\ro'}} -  \ket{\psi_D^{\ro}}\right\|_2\quad \text{(\cref{thm:trace-dist-euclidian-dist})}\\
        &\leq 2 \cdot \sqrt{D \cdot \sum_{\substack{(i, x_i) : \\\ro(i, x_i) \neq \ro'(i, x_i)}} w_{i, x_i}^{\leq D}(\ro)}\quad \text{(\cref{thm:swapping-lemma})}\\
        &\leq 2 \cdot \sqrt{D \cdot \sum_{i \in I_2} w_{i, x_i}^{\leq D}(\ro)}\\
        &\leq 2 \cdot \sqrt{D \cdot \sum_{i \in I_2} \frac{p^2}{16 Q n}}\\
        &= 2 \cdot \sqrt{\frac{D|I_2| p^2}{16Qn}}\\
        &\leq 2 \cdot \sqrt{\frac{Q n p^2}{16Qn}}\\
        &= \frac{p}{2}\\
        \Pr[\bfX = \bfx|\RO = \ro] - \frac{p}{2}&\leq \Pr[\bfX = \bfx|\RO = \ro']\\
        \Pr[\bfX = \bfx|\RO = \ro] - \frac{1}{2} \cdot \Pr[\bfX = \bfx|\RO = \ro]&\leq\\
        \frac{1}{2} \cdot \Pr[\bfX = \bfx|\RO = \ro] &\leq \Pr[\bfX = \bfx|\RO = \ro']
    \end{align*}
    We used the fact that $\frac{p}{2} \leq \frac{1}{2} \cdot \Pr[\bfX = \bfx|\RO = \ro]$.
    \end{proof}

    \paragraph{Finishing the proof:} Now we will show that $\Pr[S]\leq 2^{-(s-1)}$. 

    Let $\Pr[T_{\ro, \bfx}]$ be over the randomness of sampling $\ro' \gets \cH$ and $\bfx \gets \cA^{\ro'}$ given $\ro'$. Since the sets $\left(T_{\ro, \bfx}\right)_{(\ro, \bfx) \in S}$ are mutually disjoint,
    \begin{align*}
        1 &\geq \sum_{(\ro, \bfx) \in S} \Pr[T_{\ro, \bfx}]\\
        &= \sum_{(\ro, \bfx) \in S} \sum_{(\ro', \bfx) \in T_{\ro, \bfx}} \frac{1}{|\cH|} \cdot \Pr[\bfX = \bfx|\RO = \ro']\\
        &\geq \sum_{(\ro, \bfx) \in S} \sum_{(\ro', \bfx) \in T_{\ro, \bfx}} \frac{1}{2 |\cH|} \cdot \Pr[\bfX = \bfx|\RO = \ro]\\
        &= \sum_{(\ro, \bfx) \in S} |T_{\ro, \bfx}| \cdot \frac{1}{2|\cH|} \cdot \Pr[\bfX = \bfx|\RO = \ro]\\
        &\geq \sum_{(\ro, \bfx) \in S} 2^{s} \cdot \frac{1}{2 |\cH|} \cdot \Pr[\bfX = \bfx|\RO = \ro]\\
        &= 2^{s - 1} \cdot \sum_{(\ro, \bfx) \in S} \frac{1}{|\cH|} \cdot \Pr[\bfX = \bfx|\RO = \ro]\\
        &= 2^{s - 1} \cdot \Pr[S]\\
        2^{-(s - 1)} &\geq \Pr[S]
    \end{align*}

    We've shown that the conditions of \cref{thm:must-heavy-query} are satisfied with probability $\leq 2^{-(s - 1)}$.
\end{proof}

\subsection*{Low-depth adversaries cannot heavily query a correct answer.}
Here we prove that if the adversary's query depth is $o(\log \secp)$, then with overwhelming probability over $\RO$, $\cA^\RO$ does not \textit{heavily query} any correct answer $\bfx$. Heavy querying means that many symbols of $\bfx$ each receive large query weight from $\cA^\RO$.

\begin{lemma}\label{thm:2-query-security}
    Let $p(\secp)$ be any function satisfying $p(\secp) = \omega\left(2^{-\frac{1}{2} \cdot \left(\secp^{c/2}\right)}\right)$. Let $D(\secp)$ be any function satisfying $1 \leq D(\secp) = o\left(\log \secp\right)$. Let $W(\secp)$ be any function satisfying $1 \leq W(\secp)  = O(\poly(\secp))$, and let $s = \lfloor \zeta n \rfloor$. Let $\cA$ have query width $W$ and query depth $D$, making $Q = W \cdot D$ queries in total.

    Then with overwhelming probability over the randomness of $\RO$, $\RO$ satisfies the following condition: 
    \begin{enumerate}
        \item For all $\bfx$ such that $\bfx$ is correct ($\bfx \in C$ and $\RO(\bfx) = \mathbf{0}$), there exists \textit{no} set $I \subseteq [n]$ of size $\geq n - s$ such that for all $i \in I$,
        \[w_{i, x_i}^{\leq D}(\RO) \geq \frac{p^2}{16 Q n}\]
    \end{enumerate}
\end{lemma}

\begin{proof}
$ $\\\\
    \noindent\textbf{Query Weight Thresholds:}
    Let us define a threshold weight given to a symbol after $q$ query layers. For each $q \in \{0, 1, \dots, D\}$, let the threshold be
    \[t_q = \left(\frac{2 Q n}{\ell}\right)^{\left(4^{-q}\right)}\]


    \begin{claim}\label{thm:bounds-on-t-q}
        For any $q \in \{0, 1, \dots, D\}$ and sufficiently large $\secp$, 
        \[\frac{Q}{\ell} \leq t_q \leq 1\]
    \end{claim}
    \begin{proof}
    We know that
    \begin{align*}
        \ell &= 2^{\left(\secp^c\right)}\\
        Q &= W \cdot D = O(\poly(\secp)) \\
        n &= 2^{\lfloor \log \secp \rfloor} - 1 \leq \secp\\
        1 &\leq n \quad \text{for sufficiently large $\secp$}
    \end{align*}
    Therefore,
    \begin{align*}
        2 Q n &\leq \ell \quad \text{for sufficiently large $\secp$}\\
        \frac{2 Q n}{\ell} &\leq 1\\
    \end{align*}
    Additionally, $4^{-q} \in (0, 1]$. Then
    \begin{align*}
        \frac{2 Q n}{\ell} &\leq \left(\frac{2 Q n}{\ell}\right)^{\left(4^{-q}\right)} \leq 1\\
        \frac{2 Q n}{\ell} &\leq t_q \leq 1\\
        \frac{Q}{\ell} &\leq t_q \leq 1
    \end{align*}
    \end{proof}

    \begin{claim}\label{thm:upper-bound-on-t-q}
        For any $q \in \{0, 1, \dots, D\}$ and sufficiently large $\secp$,
        \[t_q \leq \frac{p^2}{16 Q n}\]
    \end{claim}
    \begin{proof}
    First,
    \begin{align*}
        q &\leq D \leq \frac{1}{4} \cdot \left(c \log \secp - 2\right) \quad \text{for sufficiently large $\secp$}\\
        -q &\geq \frac{1}{4} \cdot \left(2 - c \log \secp\right)\\
        4^{-q} &\geq 4^{\frac{1}{4} \cdot \left(2 - c \log \secp\right)}\\
        &= 2^{\frac{2}{4} \cdot \left(2 - c \log \secp\right)}\\
        &= 2^{\left(1 - \frac{c}{2} \cdot \log \secp\right)}\\
        &= 2 \cdot 2^{- \frac{c}{2} \cdot \log \secp}\\
        &= 2 \cdot \secp^{-\frac{c}{2}}
    \end{align*}

    Second,
    \begin{align*}
        p(\secp) &= \omega\left(2^{-\frac{1}{2} \cdot \left(\secp^{c/2}\right)}\right)\\
        p(\secp) &\geq 2^{-\frac{1}{2} \cdot \left(\secp^{c/2}\right)} \quad \text{for sufficiently large $\secp$}\\
        p^2(\secp) &\geq 2^{-\left(\secp^{c/2}\right)}


    \end{align*}

    Third, the following are true for sufficiently large $\secp$:
    \begin{equation}\label{eq:true-when-secp-is-large}
    \begin{split}
        \frac{2 Q n}{\ell} &\leq 1\\
        1 &\leq 2 Q n\\
        2 \cdot \secp^{-\frac{c}{2}} &\leq 1\\
        \frac{32 Q^2 n^2}{2^{\left(\secp^{\frac{c}{2}}\right)}} &\leq 1
    \end{split}
    \end{equation}
    Let us assume that $\secp$ is large enough that all of the conditions in \cref{eq:true-when-secp-is-large} are satisfied.

    Fourth, 
    \begin{align*}
        \frac{2 Q n}{\ell} &\leq 1\\
        \left(\frac{2 Q n}{\ell}\right)^{\left(4^{-q}\right)} &\leq \left(\frac{2 Q n}{\ell}\right)^{\left(2 \cdot \secp^{-\frac{c}{2}}\right)}\\
        t_q &\leq \left(2 Q n\right)^{\left(2 \cdot \secp^{-\frac{c}{2}}\right)} \cdot \ell^{\left(-2 \cdot \secp^{-\frac{c}{2}}\right)}\\
        &\leq \left(2 Q n\right) \cdot \ell^{\left(-2 \cdot \secp^{-\frac{c}{2}}\right)}\\
        &= \left(2 Q n\right) \cdot \left(2^{\left(\secp^c\right)}\right)^{\left(-2 \cdot \secp^{-\frac{c}{2}}\right)}\\
        &= \left(2 Q n\right) \cdot 2^{\left(\secp^c\right) \cdot \left(-2\right) \cdot \left(\secp^{-\frac{c}{2}}\right)}\\
        &= \left(2 Q n\right) \cdot 2^{-2 \cdot \left(\secp^{\frac{c}{2}}\right)}\\
        &= \left(2 Q n\right) \cdot \left(2^{-\left(\secp^{\frac{c}{2}}\right)}\right) \cdot \left(16 Q n\right) \cdot \frac{1}{16 Q n} \cdot \left(2^{-\left(\secp^{\frac{c}{2}}\right)}\right)\\
        &\leq \left(2 Q n\right) \cdot \left(2^{-\left(\secp^{\frac{c}{2}}\right)}\right) \cdot \left(16 Q n\right) \cdot \frac{1}{16 Q n} \cdot p^2\\
        &\leq \frac{32 Q^2 n^2}{2^{\left(\secp^{\frac{c}{2}}\right)}} \cdot \frac{p^2}{16 Q n}\\
        &\leq \frac{p^2}{16 Q n} \quad \text{for sufficiently large $\secp$}
    \end{align*}
    \end{proof}

    \begin{claim}\label{thm:lower-bound-t-q}
        For any $q \in \{1, 2, \dots, D\}$ and sufficiently large $\secp$, 
        \[\frac{Q}{\ell} + 2Q \cdot \sqrt{D n \cdot t_{q-1}} \leq t_q\]
    \end{claim}
    \begin{proof}
    First,
    \begin{align*}
        D &\leq \frac{1}{4} \cdot \left(c \cdot \log \secp - 2\right) \quad \text{for sufficiently large $\secp$}\\
        q &\leq D \leq \frac{1}{4} \cdot \left(c \cdot \log \secp - 2\right)\\
        2q &\leq \frac{1}{2} \cdot \left(c \cdot \log \secp - 2\right) = \frac{c}{2} \cdot \log \secp - 1\\
        2q - 1 &\leq \frac{c}{2} \cdot \log \secp - 2\\
        1 - 2q &\geq 2 - \frac{c}{2} \cdot \log \secp\\
        2^{1 - 2q} &\geq 2^{2 - \frac{c}{2} \cdot \log \secp}\\
        &= 4 \cdot \secp^{-c/2}
    \end{align*}

    Second,

    \begin{align*}
        \frac{\ell}{2 Q n} &= 2^{\left(\secp^c - O(\log \secp)\right)}\\
        \left(\frac{\ell}{2 Q n}\right)^{4 \cdot \secp^{-c/2}} &= 2^{\left(\secp^c - O(\log \secp)\right) \cdot \left(4 \cdot \secp^{-c/2}\right)}\\
        &= 2^{\left(4 \cdot \secp^{c/2} - O(\secp^{-c/2} \cdot \log \secp)\right)}\\
        &= 2^{\Theta\left(\secp^{c/2}\right)}\\
        &\geq 9 W^2 D^3 n \quad \text{for sufficiently large $\secp$}
    \end{align*}

    Third,
    \begin{align*}
        \left(\frac{\ell}{2 Q n}\right)^{\left(2^{1-2q}\right)} &= \left(\frac{2 Q n}{\ell}\right)^{\left(-1 \cdot 2^{1-2q}\right)} = \left(\frac{2 Q n}{\ell}\right)^{\left(-2 \cdot 4^{-q}\right)}\\
        &= \left(\frac{2 Q n}{\ell}\right)^{\left[(2 - 4) \cdot 4^{-q}\right]} = \left(\frac{2 Q n}{\ell}\right)^{\left[2 \cdot 4^{-q} - 4^{-(q-1)}\right]}\\
        &= \frac{\left[\left(\frac{2 Q n}{\ell}\right)^{\left(4^{-q}\right)}\right]^2}{\left(\frac{2 Q n}{\ell}\right)^{\left(4^{-(q-1)}\right)}} = \frac{t_q^2}{t_{q-1}}
    \end{align*}

    Finally,
    \begin{align*}
        \ell &\geq 2 Q n \quad \text{for sufficiently large $\secp$}\\
        \frac{\ell}{2 Q n} &\geq 1\\
        \left(\frac{\ell}{2 Q n}\right)^{\left(2^{1-2q}\right)} &\geq \left(\frac{\ell}{2 Q n}\right)^{4 \cdot \secp^{-c/2}}\\
        \frac{t_q^2}{t_{q-1}} &\geq 9W^2D^3n\\
        t_q &\geq 3 DW \sqrt{D n \cdot t_{q-1}} = 3 Q \sqrt{D n \cdot t_{q-1}}\\
        &= Q \sqrt{D n} \cdot \sqrt{t_{q-1}} + 2Q \sqrt{D n \cdot t_{q-1}}\\
        &\geq \sqrt{t_{q-1}} + 2Q \sqrt{D n \cdot t_{q-1}} \quad \text{because $D,Q, n \geq 1$ for sufficiently large $\secp$}\\
        &\geq t_{q-1} + 2Q \sqrt{D n \cdot t_{q-1}} \quad \text{because $t_{q-1} \leq 1$ for sufficiently large $\secp$ (\cref{thm:bounds-on-t-q})}\\
        &\geq \frac{Q}{\ell} + 2Q \sqrt{D n \cdot t_{q-1}} \quad \text{because $t_{q-1} \geq \frac{Q}{\ell}$ for sufficiently large $\secp$ (\cref{thm:bounds-on-t-q})}
    \end{align*}
    \end{proof}

    \paragraph{Constructing the Good Set:} Let us construct a set $S$ of ``good'' oracles $\ro$. For every $\ro \in \cH$ that violates the condition of \cref{thm:2-query-security}, pick an $\bfx$ such that: 
    \begin{enumerate}
        \item $\bfx$ is correct ($\bfx \in C$ and $\ro(\bfx) = \mathbf{0}$), and
        \item there exists a set $I \subseteq [n]$ of size $\geq n - s$ such that for all $i \in I$,
        \[w_{i, x_i}^{\leq D}(\ro) \geq \frac{p^2}{16 Q n}\]
    \end{enumerate}
    Such an $\bfx$ must exist. Then add this $(\ro, \bfx)$ pair to $S$. Note that no two entries of $S$ have the same $\ro$-value, so the size of $S$ is the number of $\ro$-values that violate the condition of \cref{thm:2-query-security}. Our goal is to show that $\frac{|S|}{|\cH|} = \negl(\secp)$. This implies that with overwhelming probability over the choice of $\ro$, the condition of \cref{thm:2-query-security} is satisfied.

    \paragraph{Constructing the Bad Set:} For any $(\ro, \bfx) \in S$, we will construct a set of ``bad'' oracles $T_{\ro,\bfx}$ where $\bfx$ is no longer correct, but $\cA$ still wastes query weight on $\bfx$. 

    First, let us say that \textbf{$\cA^\ro$ heavily queries $\bfx$} if there exists a set $I_1 \subseteq [n]$ of size $|I_1| \geq n - s$ such that for all $i \in I_1$,
    \[w_{i, x_i}^{\leq D}(\ro) \geq \frac{Q}{\ell}\]

    Additionally, let us say that \textbf{$\cA^\ro$ strongly-heavily queries $\bfx$ after $q$ queries} if there exists a set $I_1 \subseteq [n]$ of size $|I_1| \geq n-s$ such that for all $i \in I_1$,
    \[w_{i, x_i}^{\leq q}(\ro) \geq t_q\]

    Second, let $q^*$ be the first query in $[D]$ for which $\cA^\ro$ strongly-heavily queries $\bfx$ after $q^*$ queries.

    Such a $q^*$ must exist. Since $(\ro, \bfx) \in S$, there exists a set $I_1 \subseteq [n]$ of size $\geq n - s$ such that for all $i \in I_1$,
    \[w_{i, x_i}^{\leq D}(\ro) \geq \frac{p^2}{16 Q n} \geq t_D\]
    So $\cA^\ro$ strongly-heavily queries $\bfx$ after $D$ queries.

    Third, let $I_2 \subseteq [n]$ be the set of indices of $\bfx$ of size $|I_2| = s + 1$ that receive the smallest weight on the first $q^*-1$ queries. Formally, we require that for all $i \in I_2$ and all $i' \in [n] \backslash I_2$,
    \[w_{i, x_i}^{\leq q^*-1}(\ro) \leq w_{i', x_{i'}}^{\leq q^*-1}(\ro)\]

    Fourth, let us construct our bad set $T_{\ro, \bfx}$ as follows. Choose any non-empty subset of $\{(i, x_i)\}_{i \in I_2}$, and reprogram $\ro$ on this set, flipping the outputs from $0$ to $1$. Call the new oracle $\ro'$, and add $\ro'$ to $T_{\ro, \bfx}$. 

    \paragraph{Properties:} Let's state some useful properties of $T_{\ro, \bfx}$ and $I_2$.

    First, note that for any $\ro' \in T_{\ro, \bfx}$, $\ro'(\bfx) \neq \mathbf{0}$. Second,
    \[|T_{\ro,\bfx}| = 2^{|I_2|} - 1 = 2^{s + 1} - 1 \geq 2^{s}\]

    Third, before the $q^*$-th query, every reprogrammed symbol received small cumulative query weight.
    \begin{lemma}\label{thm:I-2-has-small-query-weight}
        For all $(\ro, \bfx) \in S$, all $i \in I_2$, and all $q \in [q^*]$,
        \begin{align*}
            w_{i, x_i}^{\leq q-1}(\ro) < t_{q^*-1}
        \end{align*}
    \end{lemma}
    \begin{proof}
        We chose $q^*$ to be the \textit{first} query in $[D]$ after which $\cA^\ro$ strongly-heavily queries $\bfx$. Then $\cA^\ro$ does not strongly-heavily query $\bfx$ after $q^* - 1$ queries. That means there does not exist a set $I_1 \subseteq [n]$ of size $|I_1| \geq n - s$ such that for all $i \in [I_1]$:
        \begin{equation}\label{eq:large-query-weight}
            w_{i, x_i}^{\leq q^*-1}(\ro) \geq t_{q^* - 1}
        \end{equation}
        Then the number of $i$-values in $[n]$ for which \cref{eq:large-query-weight} is satisfied is $\leq n - s - 1$. The number of $i$-values for which \cref{eq:large-query-weight} is not satisfied is
        \[\geq n - \left(n - s - 1\right) = s + 1 \] 

        Since $I_2$ contains the $s + 1$ indices with the smallest values of $w_{i, x_i}^{\leq q^*-1}(\ro)$, that means that for any $i \in I_2$,
        \[w_{i, x_i}^{\leq q^*-1}(\ro) < t_{q^* - 1}\]
        Since $q \leq q^*$,
        \begin{align*}
            w_{i, x_i}^{\leq q-1}(\ro) &\leq w_{i, x_i}^{\leq q^*-1}(\ro)\\
            &< t_{q^* - 1}
        \end{align*}
    \end{proof}

    Fourth, even if we replace a good $\ro$ with a bad $\ro' \in T_{\ro, \bfx}$, the adversary will still heavily query $\bfx$.
    \begin{lemma}
        For any $(\ro, \bfx) \in S$, any $\ro' \in T_{\ro, \bfx}$, and sufficiently large $\secp$, $\cA^{\ro'}$ heavily queries $\bfx$.
    \end{lemma}
    \begin{proof}
        Let $I_1, I_2$ be the sets defined in the construction of $T_{\ro, \bfx}$. That's to say, $I_1$ is a set $\subseteq [n]$ of size $|I_1| \geq n - s$ such that for all $i \in I_1$, 
        \[w_{i, x_i}^{\leq q^*}(\ro) \geq t_{q^*}\]
        And $I_2 \subseteq [n]$ is a set of size $|I_2| = s+1$ such that for all $i \in I_2$
        \[w_{i, x_i}^{\leq q^*-1}(\ro) < t_{q^*-1}\]

        Next, for any $q \in [q^*]$, any $\ro' \in T_{\ro, \bfx}$, and any $i \in I_1$:
        \begin{align*}
            w_{i, x_i}^{q}(\ro) - w_{i, x_i}^{q}(\ro') &= \sum_{k \in [W]} \Tr\left[\left(\ketbra{i,x_i}_{R_{Q_k}} \otimes \mathbb{I}_{R \backslash R_{Q_k}}\right) \left(\ketbra{\psi_{q-1}^\ro} - \ketbra{\psi_{q-1}^{\ro'}}\right)\right]\\

            &\leq \sum_{k \in [W]} \mathsf{TraceDist}\left(\ket{\psi^{\ro}_{q-1}},\ket{\psi^{\ro'}_{q-1}}\right) = W \cdot \mathsf{TraceDist}\left(\ket{\psi^{\ro}_{q-1}},\ket{\psi^{\ro'}_{q-1}}\right)\\
            &\leq W \cdot \left\|\ket{\psi^{\ro}_{q-1}} - \ket{\psi^{\ro'}_{q-1}}\right\|_2 \quad \text{(\cref{thm:trace-dist-euclidian-dist})}\\
            &\leq 2W \cdot \sqrt{(q-1) \cdot \sum_{\substack{(i',x'):\\
            \ro(i',x') \neq \ro'(i',x')}} w_{i',x'}^{\leq q-1}(\ro)} \quad \text{(\cref{thm:swapping-lemma})}\\
            &\leq 2W \cdot \sqrt{(q-1) \cdot \sum_{i \in I_2} w_{i,x_i}^{\leq q-1}(\ro)}\\
            &\leq 2W \cdot \sqrt{(q-1) \cdot \sum_{i \in I_2} t_{q^*-1}} \quad \text{(\cref{thm:I-2-has-small-query-weight})}\\
            &=  2W \cdot \sqrt{(q-1) \cdot |I_2| \cdot t_{q^*-1}}\\
            &\leq 2W \cdot \sqrt{(q-1) \cdot n \cdot t_{q^*-1}}\\
            &\leq 2W \cdot \sqrt{D n \cdot t_{q^*-1}}\\
            w_{i, x_i}^{q}(\ro) - 2W \cdot \sqrt{D n \cdot t_{q^*-1}} &\leq w_{i, x_i}^{q}(\ro')
        \end{align*}

        Now let us sum over all $q \in [q^*]$.
        \begin{align*}
            \sum_{q = 1}^{q^*} w_{i, x_i}^{q}(\ro') &\geq \sum_{q=1}^{q^*} \left(w_{i, x_i}^{q}(\ro) - 2W \cdot \sqrt{D n \cdot t_{q^*-1}}\right)\\
            w_{i, x_i}^{\leq q^*}(\ro') &\geq w_{i, x_i}^{\leq q^*}(\ro) - q^* \cdot 2W \cdot \sqrt{D n \cdot t_{q^*-1}}\\
            &\geq t_{q^*} - q^* \cdot 2W \cdot \sqrt{D n \cdot t_{q^*-1}}\\
            &\geq t_{q^*} - D \cdot 2W \cdot \sqrt{D n \cdot t_{q^*-1}}\\
            &= t_{q^*} - 2Q \cdot \sqrt{D n \cdot t_{q^*-1}}\\
            &\geq \frac{Q}{\ell} + 2Q \cdot \sqrt{D n \cdot t_{q^*-1}} - 2Q \cdot \sqrt{D n \cdot t_{q^*-1}} \quad \text{(\cref{thm:lower-bound-t-q})}\\
            &= \frac{Q}{\ell} \\
            w_{i, x_i}^{\leq D}(\ro') &\geq \frac{Q}{\ell}
        \end{align*}
        Therefore, $\cA^{\ro'}$ heavily queries $\bfx$.
    \end{proof}


    \begin{claim}
        The number of codewords that $\cA^{\ro'}$ heavily queries is $\leq L := 2^{\tilde{O}(\secp^{c'})}$.
    \end{claim}
    \begin{proof}
        The total cumulative query weight given to all inputs is $\leq Q = D \cdot W$ (\cref{thm:total-cumulative-query-weight}). The number of inputs $(i, x)$ with cumulative query weight $w_{i, x}^{\leq D}(\ro') \geq \frac{Q}{\ell}$ is 
        \[\leq Q \cdot \frac{\ell}{Q} = \ell\] 
        If $\cA^{\ro'}$ heavily queries $\bfx$ then at least $n - s$ coordinates of $\bfx$ belong to the list of inputs that have cumulative query weight $\geq \frac{Q}{\ell}$. Note that 
        \[n-s \geq n - \zeta \cdot n = (1 - \zeta) \cdot n\]
        Then the list recoverability property (\cref{thm:list-recoverability}) says that the number of codewords $\bfx$ that satisfy this property is $\leq L$.
    \end{proof}

    \begin{claim}
        Any $\ro'$ belongs to $T_{\ro, \bfx}$ for at most $L$ values of $(\ro, \bfx) \in S$.
    \end{claim}
    \begin{proof}
        Assume toward contradiction that there are $L+1$ distinct values of $(\ro, \bfx) \in S$ such that $\ro' \in T_{\ro, \bfx}$. Call them $(h_j, \bfx_j)_{j \in [L+1]}$. We know that $\cA^{\ro'}$ heavily queries each $\bfx_j$, but there are at most $L$ codewords that $\cA^{\ro'}$ heavily queries. By the pigeonhole principle, there are two different values $j, j' \in [L+1]$ such that $\bfx_j = \bfx_{j'}$.

        Furthermore, $h_{j}$ can be constructed from $\ro'$ and $\bfx_{j}$ by reprogramming $\ro'$ to map $\bfx_{j}$ to $\mathbf{0}$. By the same procedure, $h_{j'}$ can be constructed from $\ro'$ and $\bfx_{j'}$. Since $\bfx_j = \bfx_{j'}$, this implies that $h_j = h_{j'}$ because they are constructed from $(\ro', \bfx_j)$ by the same procedure. In summary $(h_j, \bfx_j) = (h_{j'}, \bfx_{j'})$, which contradicts the claim that each $(h_{j''}, \bfx_{j''})$ is distinct. Therefore the initial assumption must be false, so in fact there are at most $L$ values of $(\ro,\bfx) \in S$ for which $\ro' \in T_{\ro, \bfx}$.
    \end{proof}

    Now we can finish the proof. Since each $\ro' \in \cH$ belongs to at most $L$ different sets $T_{\ro, \bfx}$,
    \begin{align*}
        |\cH| \cdot L &\geq \sum_{\ro' \in \cH} \sum_{(\ro, \bfx) \in S}  \mathbbm{1}_{\ro' \in T_{\ro, \bfx}}\\
        &= \sum_{(\ro, \bfx) \in S} \sum_{\ro' \in \cH} \mathbbm{1}_{\ro' \in T_{\ro, \bfx}}\\
        &= \sum_{(\ro, \bfx) \in S} |T_{\ro, \bfx}|\\
        &\geq \sum_{(\ro, \bfx) \in S} 2^{s}\\
        &= |S| \cdot 2^{s} = |S| \cdot 2^{\lfloor \zeta n \rfloor}\\
        &= |S| \cdot 2^{\Omega(\secp)}\\
        \frac{L}{2^{\Omega(\secp)}} &\geq \frac{|S|}{|\cH|}\\
        2^{\tilde{O}(\secp^{c'}) - \Omega(\secp)} &=\\
        \negl(\secp) &=
    \end{align*}
    $2^{\tilde{O}(\secp^{c'}) - \Omega(\secp)} = \negl(\secp)$ because $c' < 1$.

    We've shown that $\frac{|S|}{|\cH|}$ is $\negl(\secp)$, which completes the proof.    
\end{proof}

\subsection*{Finishing the proof}

Let us assume toward contradiction that \cref{thm:CR-for-depth-bounded-adversaries} is false. Then there is some $D = o(\log \secp)$, some $\minent = o(\secp^{c/2})$, some $W = \poly(\secp)$, some inverse-polynomial $\delta(\secp)$, and some adversary $\cA$ making $D$ layers of $W$ parallel queries such that 
\begin{align*}
    \Pr_{\RO}\left[\Pr\left[\Verify^\RO [1^\secp, 1^\minent, \cA^\RO(1^\secp, 1^\minent)] \neq \bot\right] \geq \delta(\secp) \land \Minent\left(\cA^\RO_\top (1^\secp, 1^\minent)\right) \leq \minent(\secp)\right] = \text{non-negl}(\secp).
\end{align*}

Let us define two parameters.
\begin{align*}
    \text{Let } p(\secp) &= \delta(\secp) \cdot 2^{-\minent(\secp)}\\
    s(\secp) &= \lfloor \zeta n \rfloor
\end{align*}

Let us also define two events based on $\RO$:
\begin{itemize}
    \item Let $\text{Event}_1$ be the event that $\RO$ satisfies:
    \[\Pr\left[\Verify^\RO [1^\secp, 1^\minent, \cA^\RO(1^\secp, 1^\minent)] \neq \bot\right] \geq \delta(\secp) \land \Minent\left(\cA^\RO_\top (1^\secp, 1^\minent)\right) \leq \minent(\secp)\]
    \item Let $\text{Event}_2$ be the event that $\RO$ satisfies the following condition:

    For all $\bfx$ such that $\bfx$ is correct ($\bfx \in C$ and $\RO(\bfx) = \mathbf{0}$), there exists \textit{no} set $I \subseteq [n]$ of size $\geq n - s$ such that for all $i \in I$,
        \[w_{i, x_i}^{\leq D}(\RO) \geq \frac{p^2}{16 Q n}\]
\end{itemize}
We have that $\Pr_\RO[\text{Event}_1] = \text{non-negl}(\secp)$ if the adversary breaks the min-entropy property.

Finally, let us define $\text{Event}_3$ based on $(\RO, \bfX)$ as the event that the conditions of \cref{thm:must-heavy-query} are satisfied.
\begin{itemize}
    \item Let $\text{Event}_3$ be the event that $(\RO, \bfX)$ have values $(\ro, \bfx)$ that satisfy:
    \begin{enumerate}
        \item $\cA^\ro$ gives small query weight to many positions of $\bfx$: There exists \emph{no} set $I \subseteq [n]$ of size $\geq n - s$ such that for all $i \in I$,
        \[w_{i, x_i}^{\leq D}(\ro) \geq \frac{p^2}{16 Q n}\]
        \item $\bfx$ has high probability given $\ro$: $\Pr[\bfX = \bfx |\RO = \ro] \geq p$.
        \item $\bfx$ is correct: $\bfx \in C$ and $\ro(\bfx) = \mathbf{0}$.
    \end{enumerate}
\end{itemize}

\begin{lemma}
    Let $\ro$ be any value of $\RO$ that satisfies $\text{Event}_1$ and $\text{Event}_2$. Then there exists an $\bfx^\ro$ such that $(\ro, \bfx^\ro)$ satisfy $\text{Event}_3$.
\end{lemma}
\begin{proof}
The first condition of $\text{Event}_1$ is $\Pr\left[\Verify^\RO [1^\secp, 1^\minent, \cA^\RO(1^\secp, 1^\minent)] \neq \bot\right] \geq \delta(\secp)$, which is equivalent to:
    \[\Pr_\bfX[\bfX \in C \land \RO(\bfX) = \mathbf{0} | \RO = \ro] \geq \delta(\secp).\]
Next, 
\begin{align*}
    \Minent\left(\cA^\RO_\top (1^\secp, 1^\minent)\right) &= - \log\left(\max_{\bfx} \Pr_\bfX\left[\bfX = \bfx | \RO = \ro, (\bfX \in C \land \RO(\bfX) = \mathbf{0})\right]\right)
\end{align*}
Furthermore, for any $\bfx$ that is correct ($\bfx \in C \land \ro(\bfx) = \mathbf{0}$),
\begin{align*}
    \Pr_\bfX\left[\bfX = \bfx | \RO = \ro, (\bfX \in C \land \RO(\bfX) = \mathbf{0})\right] &= \frac{\Pr_\bfX\left[\bfX = \bfx, (\bfX \in C \land \RO(\bfX) = \mathbf{0}) | \RO = \ro\right]}{\Pr_\bfX\left[\bfX \in C \land \RO(\bfX) = \mathbf{0}|\RO = \ro\right]}\\
    &= \frac{\Pr_\bfX\left[\bfX = \bfx | \RO = \ro\right]}{\Pr_\bfX\left[\bfX \in C \land \RO(\bfX) = \mathbf{0}|\RO = \ro\right]}\\
    &\leq \frac{\Pr_\bfX\left[\bfX = \bfx | \RO = \ro\right]}{\delta(\secp)}
\end{align*}

The second condition of $\text{Event}_1$ is $\Minent\left(\cA^\RO_\top (1^\secp, 1^\minent)\right) \leq \minent(\secp)$, which implies that:
\begin{align*}
    -\log\left(\max_{\bfx} \Pr_\bfX[\bfX = \bfx | \RO = \ro, (\bfX \in C \land \RO(\bfX) = \mathbf{0})]\right) &\leq \minent(\secp)\\
    \log\left(\max_{\bfx} \Pr_\bfX[\bfX = \bfx | \RO = \ro, (\bfX \in C \land \RO(\bfX) = \mathbf{0})]\right) &\geq -\minent(\secp)\\
    \max_{\bfx} \Pr_{\bfX}[\bfX = \bfx | \RO = \ro, (\bfX \in C \land \RO(\bfX) = \mathbf{0})] &\geq 2^{-\minent(\secp)}
\end{align*}
Then there exists an $\bfx^\ro$ such that
\begin{align*}
    \Pr_\bfX[\bfX = \bfx^\ro | \RO = \ro, (\bfX \in C \land \RO(\bfX) = \mathbf{0})] &\geq 2^{-\minent(\secp)} > 0
\end{align*}
Furthermore, this $\bfx^\ro$ is correct ($\bfx^\ro \in C \land \ro(\bfx^\ro) = \mathbf{0}$) because otherwise, $\Pr_\bfX[\bfX = \bfx^\ro | \RO = \ro, (\bfX \in C \land \RO(\bfX) = \mathbf{0})] = 0$. Then
\begin{align*}
    \frac{\Pr_\bfX\left[\bfX = \bfx^\ro | \RO = \ro\right]}{\delta(\secp)} &\geq \Pr_\bfX[\bfX = \bfx^\ro | \RO = \ro, (\bfX \in C \land \RO(\bfX) = \mathbf{0})]\\
    &\geq 2^{-\minent(\secp)}\\
    \Pr_\bfX\left[\bfX = \bfx^\ro | \RO = \ro\right] &\geq \delta(\secp) \cdot 2^{-\minent(\secp)}\\
    &= p(\secp)
\end{align*}

In summary, if $\text{Event}_1$ occurs, then there exists an $\bfx^\ro$ such that:
\begin{itemize}
    \item $\bfx^\ro$ is correct: $\bfx^\ro \in C \land \ro(\bfx^\ro) = \mathbf{0}$, and 
    \item $\Pr_\bfX\left[\bfX = \bfx^\ro | \RO = \ro\right] \geq p(\secp)$.
\end{itemize}

Furthermore, since this $\bfx^\ro$ is correct, then $\text{Event}_2$ implies that this $\bfx^\ro$-value also satisfies the following condition:
\begin{itemize}
    \item There exists \textit{no} set $I \subseteq [n]$ of size $\geq n - s$ such that for all $i \in I$,
        \[w_{i, x^\ro_i}^{\leq D}(\ro) \geq \frac{p^2}{16 Q n}\]
\end{itemize}
This shows that $(\ro, \bfx^\ro)$ satisfy all the conditions of $\text{Event}_3$.
\end{proof}

\begin{lemma}
    $\Pr_\RO[\text{Event}_2]$ is overwhelming.
\end{lemma}
\begin{proof}
\Cref{thm:2-query-security} says that $\Pr_\RO[\text{Event}_2]$ is overwhelming as long as $p(\secp) = \omega\left(2^{-\frac{1}{2} \cdot \left(\secp^{c/2}\right)}\right)$. So it suffices to prove that $p$ satisfies the condition of \cref{thm:2-query-security}.

\begin{claim}
    $p(\secp) = \omega\left(2^{-\frac{1}{2} \cdot \left(\secp^{c/2}\right)}\right)$.
\end{claim}
\begin{proof}
    $\delta(\secp)$ is inverse-polynomial, so there exists a $d > 0$ such that
    \begin{align*}
        \delta(\secp) &= \secp^{-d} = 2^{- d \cdot \log \secp}\\
        p(\secp) &= 2^{- d \cdot \log \secp} \cdot 2^{-\minent(\secp)}\\
        &= 2^{-\left[d \cdot \log \secp + \minent(\secp)\right]}
    \end{align*}
    Next, note that 
    \begin{align*}
        \minent(\secp) &= o(\secp^{c/2})\\
        d \cdot \log \secp &= o(\secp^{c/2})\\
        \secp^{c/2} &= \omega(1)
    \end{align*}

    Then for any constant $\varepsilon > 0$, and for sufficiently large $\secp$,
    \begin{align*}
        \minent(\secp) &\leq \frac{1}{8} \cdot \secp^{c/2}\\
        d \cdot \log \secp &\leq \frac{1}{8} \cdot \secp^{c/2}\\
        4 \cdot \log \varepsilon &\leq \secp^{c/2}
    \end{align*}
    In this case,
    \begin{align*}
        \log \varepsilon &\leq \frac{1}{4} \cdot \secp^{c/2}\\
        -\frac{1}{4} \cdot \secp^{c/2} &\leq -\log \varepsilon\\\\
        d \cdot \log \secp + \minent(\secp) &\leq \frac{1}{4} \cdot \secp^{c/2}\\
        &= - \frac{1}{4} \cdot \secp^{c/2} + \frac{1}{2} \cdot \secp^{c/2}\\
        &\leq - \log \varepsilon + \frac{1}{2} \cdot \secp^{c/2}\\
        -\left[d \cdot \log \secp + \minent(\secp)\right] &\geq \log \varepsilon - \frac{1}{2} \cdot \secp^{c/2}\\
        p(\secp) &\geq 2^{\log \varepsilon - \frac{1}{2} \cdot \secp^{c/2}}\\
        &= \varepsilon \cdot 2^{- \frac{1}{2} \cdot \secp^{c/2}}
    \end{align*}

    Therefore, $p(\secp) = \omega\left(2^{- \frac{1}{2} \cdot \secp^{c/2}}\right)$
\end{proof}

\end{proof}

\begin{lemma}
    There is some non-negligible function $\text{non-negl}(\secp)$ such that $\Pr_{\RO, \bfX}[\text{Event}_3] \geq \text{non-negl}(\secp) \cdot p(\secp)$.
\end{lemma}
\begin{proof}
    We already know that $\Pr_{\RO}[\text{Event}_1]$ is non-negligible because the adversary breaks the certifiable min-entropy property, and we proved that $\Pr_{\RO}[\text{Event}_2]$ is overwhelming. This implies that $\Pr_{\RO}[\text{Event}_1 \land \text{Event}_2]$ is non-negligible.
    \begin{align*}
        \Pr_\RO[\text{Event}_1] &= \Pr_\RO[(\text{Event}_1 \land \text{Event}_2) \lor (\text{Event}_1 \land \lnot \text{Event}_2)]\\
        &= \Pr_\RO[\text{Event}_1 \land \text{Event}_2] + \Pr_\RO[\text{Event}_1 \land \lnot \text{Event}_2]\\
        &\leq \Pr_\RO[\text{Event}_1 \land \text{Event}_2] + \Pr_\RO[\lnot \text{Event}_2]\\
        &\leq \Pr_\RO[\text{Event}_1 \land \text{Event}_2] + \negl(\secp)\\
        \Pr_\RO[\text{Event}_1 \land \text{Event}_2] &\geq \Pr_\RO[\text{Event}_1] - \negl(\secp)\\
        &= \text{non-negl}(\secp) - \negl(\secp)\\
        &= \text{non-negl}'(\secp)
    \end{align*}

    Next, if $\text{Event}_1 \land \text{Event}_2$ occur for some $\ro$, then there exists some special $\bfx^\ro$ such that $(\ro, \bfx^\ro)$ satisfy the conditions of $\text{Event}_3$. Furthermore, $\text{Event}_3$ guarantees that:
    \[\Pr_\bfX\left[\bfX = \bfx^\ro | \RO = \ro\right] \geq p(\secp)\]

    One way to satisfy the conditions of $\text{Event}_3$ is to sample an $\ro$ that satisfies the conditions of $\text{Event}_1 \land \text{Event}_2$ and then to sample the particular $\bfx^\ro$ value that is guaranteed to satisfy $\text{Event}_3$. The probability of sampling values $(\ro, \bfx^\ro)$ of this form is
    \[\geq \Pr_\RO[\text{Event}_1 \land \text{Event}_2] \cdot p(\secp) \geq \text{non-negl}(\secp) \cdot p(\secp)\]

    Then 
    \[\Pr_{\RO, \bfX}[\text{Event}_3] \geq \text{non-negl}(\secp) \cdot p(\secp)\]
\end{proof}

\begin{claim}
    $p(\secp)^{-1} \cdot 2^{-(s(\secp)-1)}$ is non-negligible.
\end{claim}
\begin{proof}
\Cref{thm:must-heavy-query} says that \[\Pr_{\RO, \bfX}[\text{Event}_3] \leq 2^{-(s(\secp)-1)}\] for all $\secp$.
This implies that there is some non-negligible function $\text{non-negl}(\secp)$ such that for all $\secp$,
\begin{align*}
    \text{non-negl}(\secp) \cdot p(\secp) &\leq \Pr_{\RO, \bfX}[\text{Event}_3] \leq 2^{-(s(\secp)-1)}
\end{align*}
For sufficiently large $\secp$, $p(\secp) > 0$ because $p(\secp) = \omega\left(2^{-\frac{1}{2} \cdot \left(\secp^{c/2}\right)}\right)$. Then for sufficiently large $\secp$,
\begin{align*}
    \text{non-negl}(\secp) &\leq p(\secp)^{-1} \cdot 2^{-(s(\secp)-1)}
\end{align*}
If $p(\secp)^{-1} \cdot 2^{-(s(\secp)-1)}$ were negligible, then $\text{non-negl}(\secp)$ would be negligible as well, which is impossible. Therefore, $p(\secp)^{-1} \cdot 2^{-(s(\secp)-1)}$ is non-negligible.
\end{proof}

On the other hand, we can show that $p(\secp)^{-1} \cdot 2^{-(s(\secp)-1)}$ is negligible.
\begin{claim}
    $p(\secp)^{-1} \cdot 2^{-(s(\secp)-1)}$ is negligible.
\end{claim}
\begin{proof}
    We have that 
    \begin{align*}
        s(\secp) &= \lfloor \zeta n \rfloor\\
        n &= 2^{\lfloor \log \secp \rfloor} - 1
    \end{align*}
    \Cref{sec:prelim-YZ-protocol} defines $\zeta = \Omega(1)$, so there exists a constant $k > 0$ such that for all $\secp$,
    \begin{align*}
        \zeta(\secp) &\geq k
    \end{align*}

    Next,
    \begin{align*}
        n &\geq 2^{\log \secp - 1} - 1 = \frac{\secp}{2} - 1\\
        s(\secp) &= \lfloor \zeta n \rfloor\\
        &\geq \zeta n - 1\\
        s(\secp) - 1 &\geq \zeta n - 2
    \end{align*}
    Then for sufficiently large $\secp$,
    \begin{align*}
        n &> \frac{\secp}{3} + \frac{2}{k} > 0\\
        s(\secp) - 1 &\geq \zeta \cdot \left(\frac{\secp}{3} + \frac{2}{k}\right) - 2\\
        &\geq k \cdot \left(\frac{\secp}{3} + \frac{2}{k}\right) - 2\\
        &= \frac{k}{3} \cdot \secp + 2 - 2 = \frac{k}{3} \cdot \secp\\
        -(s(\secp)-1) &\leq -\frac{k}{3} \cdot \secp\\
        2^{-(s(\secp)-1)} &\leq 2^{-\frac{k}{3} \cdot \secp}
    \end{align*}
    Additionally, since $p(\secp) = \omega\left(2^{-\frac{1}{2} \cdot \left(\secp^{c/2}\right)}\right)$, we have that for sufficiently large $\secp$,
    \begin{align*}
        p(\secp) &> 2^{-\frac{1}{2} \cdot \left(\secp^{c/2}\right)} > 0\\
        p(\secp)^{-1} &< 2^{\frac{1}{2} \cdot \left(\secp^{c/2}\right)}\\
        p(\secp)^{-1} \cdot 2^{-(s(\secp)-1)} &\leq 2^{\frac{1}{2} \cdot \left(\secp^{c/2}\right)} \cdot 2^{-\frac{k}{3} \cdot \secp}\\
        &\leq 2^{\frac{1}{2} \cdot \left(\secp^{c/2}\right) - \frac{k}{3} \cdot \secp}
    \end{align*}
    Finally, since $0 < c < 1$, then for sufficiently large $\secp$,
    \begin{align*}
        \frac{1}{2} \cdot \left(\secp^{c/2}\right) &\leq \frac{k}{12} \cdot \secp\\
        \frac{1}{2} \cdot \left(\secp^{c/2}\right) - \frac{k}{3} \cdot \secp &\leq \frac{k}{12} \cdot \secp  - \frac{k}{3} \cdot \secp = -\frac{k}{4} \cdot \secp\\
        2^{\frac{1}{2} \cdot \left(\secp^{c/2}\right) - \frac{k}{3} \cdot \secp} &\leq 2^{-\frac{k}{4} \cdot \secp} = \negl(\secp)\\
        p(\secp)^{-1} \cdot 2^{-(s(\secp)-1)} &\leq \negl(\secp)
    \end{align*}

    Therefore, $p(\secp)^{-1} \cdot 2^{-(s(\secp)-1)}$ is negligible.
\end{proof}

We have shown that $p(\secp)^{-1} \cdot 2^{-(s(\secp)-1)}$ is both non-negligible and negligible, which is a contradiction. Therefore, our initial assumption was false, and in fact, \cref{thm:CR-for-depth-bounded-adversaries} is true.

